/* Get zen quote and display it */
const URL=`https://zenquotes.io/api/random`;

var wifi = require("Wifi");
var http = require("http");
var log = print;

Graphics.prototype.setFontSueEllenFrancisco = function() {
  // Actual height 95 (94 - 0)
  // 1 BPP
  return this.setFontCustom(
    atob(''),
    32,
    atob("EAkNIxYdEgkPDRoeCxELERkJFRUTExYRFBUIChEbEBMfHhccHhkUGhkXFRsXIhsaFR4aGBgdGCEcGRsREQ8WFw8UFBQVFBITEwkMFQgbExAYFRAREBQRGBIQGBQIEBoc"),
    96|65536
  );
};
let img_tl = {
  width : 351, height : 143, bpp : 2,
  buffer : atob("")
};
let img_br = {
  width : 326, height : 140, bpp : 2,
  buffer : atob("")
};

function httpGet(url) {
  log("Fetch ",url);
  return new Promise((resolve,reject) => {
    var timeout = setTimeout(function() {
      reject("HTTP Timeout");
    }, 30000);
    try {
      http.get(url, function(res) {
        let d="";
        res.on('data', function(data) { d += data; });
        res.on('close', function() {
          clearTimeout(timeout);
          log("Fetch success");
          resolve(d);
        });
      });
    } catch (e) {
      log(e);
      Badge.showError(e).then(() => {
        ESP32.deepSleep(5*60*1000000); // try again in 5 mins
      });
    }
  });
}

Badge.connectWiFi().then(function() {
  return httpGet(URL);
}).then(data=>{
  json = JSON.parse(data);
  //print(json);
  return Badge.showRendering(function(g) {
    g.setColor(0).setBgColor(1).clear();
    g.setFontSueEllenFrancisco().setFontAlign(0,0);
    let lines = g.wrapString(json[0].q,700);
    let y = 260;
    if (lines.length<3) g.drawImage(img_tl,20,20);
    else y = 200;
    g.drawImage(img_br,780-img_br.width,460-img_br.height);
    g.drawString(lines.join("\n"), 400, y);
    g.setFont("28").setFontAlign(-1,0);
    g.drawString(json[0].a, 20,455);
  });
}).then(() => {
  // wake in 1 hr
  ESP32.deepSleep(60*60*1000000);
}).catch(e=>{
  Badge.showError(e).then(() => {
    ESP32.deepSleep(5*60*1000000); // try again in 5 mins
  });
});